#!/usr/bin/env python3
import sys, socket, struct, json, ssl, urllib.request, urllib.parse, time, random

HELP_TEXT = """dog ● command-line DNS client

Usage:
  dog [OPTIONS] [--] <arguments>

Examples:
  dog example.net                          Query a domain using default settings
  dog example.net MX                       ...looking up MX records instead
  dog example.net MX @1.1.1.1              ...using a specific nameserver instead
  dog example.net MX @1.1.1.1 -T           ...using TCP rather than UDP
  dog -q example.net -t MX -n 1.1.1.1 -T   As above, but using explicit arguments

Query options:
  <arguments>              Human-readable host names, nameservers, types, or classes
  -q, --query=HOST         Host name or domain name to query
  -t, --type=TYPE          Type of the DNS record being queried (A, MX, NS...)
  -n, --nameserver=ADDR    Address of the nameserver to send packets to
  --class=CLASS            Network class of the DNS record being queried (IN, CH, HS)

Sending options:
  --edns=SETTING           Whether to OPT in to EDNS (disable, hide, show)
  --txid=NUMBER            Set the transaction ID to a specific value
  -Z=TWEAKS                Set uncommon protocol-level tweaks

Protocol options:
  -U, --udp                Use the DNS protocol over UDP
  -T, --tcp                Use the DNS protocol over TCP
  -S, --tls                Use the DNS-over-TLS protocol
  -H, --https              Use the DNS-over-HTTPS protocol

Output options:
  -1, --short              Short mode: display nothing but the first result
  -J, --json               Display the output as JSON
  --color, --colour=WHEN   When to colourise the output (always, automatic, never)
  --seconds                Do not format durations, display them as seconds
  --time                   Print how long the response took to arrive

Meta options:
  -?, --help               Print list of command-line options
  -v, --version            Print version information"""

TYPES_CODES = {
    "A": 1, "NS": 2, "CNAME": 5, "SOA": 6, "PTR": 12, "HINFO": 13, "MX": 15, "TXT": 16,
    "AAAA": 28, "LOC": 29, "SRV": 33, "NAPTR": 35, "SSHFP": 44, "TLSA": 52, "CAA": 257,
    "ANY": 255
}
REV_TYPES = {v: k for k, v in TYPES_CODES.items()}
CLASSES_CODES = {"IN": 1, "CH": 3, "HS": 4}
REV_CLASSES = {v: k for k, v in CLASSES_CODES.items()}
TYPES_LIST = [
    "A", "AAAA", "CAA", "CNAME", "HINFO", "LOC", "MX", "NAPTR", "NS", "PTR", "SOA",
    "SRV", "SSHFP", "TLSA", "TXT", "ANY", "AXFR", "IXFR", "OPT", "DS", "RRSIG",
    "NSEC", "NSEC3", "NSEC3PARAM", "DNSKEY", "CDNSKEY", "CDS", "OPENPGPKEY",
    "CSYNC", "ZONEMD", "SVCB", "HTTPS", "EUI48", "EUI64", "TKEY", "TSIG", "URI",
    "WKS", "AFSDB", "APL", "CERT", "DHCID", "DLV", "HIP", "IPSECKEY", "KX", "MINFO",
    "MR", "RP", "SMIMEA", "TA", "X25"
]

def format_duration(seconds):
    if seconds == 0: return "0s"
    s = seconds % 60
    m = (seconds // 60) % 60
    h = (seconds // 3600) % 24
    d = seconds // 86400
    if d > 0: return f"{d}d{h}h{m:02d}m{s:02d}s"
    elif h > 0: return f"{h}h{m:02d}m{s:02d}s"
    elif m > 0: return f"{m}m{s:02d}s"
    else: return f"{s}s"

def read_name(data, offset):
    parts = []
    jumped = False
    max_offset = offset
    while True:
        if offset >= len(data): break
        length = data[offset]
        if length == 0:
            offset += 1
            if not jumped: max_offset = offset
            break
        elif (length & 0xC0) == 0xC0:
            if not jumped: max_offset = offset + 2
            offset = ((length & 0x3F) << 8) | data[offset + 1]
            jumped = True
        else:
            offset += 1
            parts.append(data[offset:offset+length].decode('utf-8', errors='replace'))
            offset += length
            if not jumped: max_offset = offset
    name = ".".join(parts) + "." if parts else "."
    return name, max_offset

def parse_rdata(rtype, data, offset, rdlength):
    rdata = data[offset:offset+rdlength]
    txt_output, json_data = "", {}
    if rtype == 1 and rdlength == 4:
        address = socket.inet_ntoa(rdata)
        txt_output = address; json_data = {"address": address}
    elif rtype == 28 and rdlength == 16:
        address = socket.inet_ntop(socket.AF_INET6, rdata)
        txt_output = address; json_data = {"address": address}
    elif rtype == 2:
        ns, _ = read_name(data, offset)
        txt_output = f'"{ns}"'; json_data = {"nameserver": ns}
    elif rtype == 5:
        cname, _ = read_name(data, offset)
        txt_output = f'"{cname}"'; json_data = {"domain": cname}
    elif rtype == 12:
        ptr, _ = read_name(data, offset)
        txt_output = f'"{ptr}"'; json_data = {"cname": ptr}
    elif rtype == 15:
        pref = struct.unpack("!H", rdata[:2])[0]
        ex, _ = read_name(data, offset+2)
        txt_output = f'{pref} "{ex}"'; json_data = {"preference": pref, "exchange": ex}
    elif rtype == 16:
        msgs = []; i = 0
        while i < rdlength:
            l = rdata[i]; i += 1
            msgs.append(rdata[i:i+l].decode('utf-8', errors='replace')); i += l
        txt_output = " ".join(f'"{m}"' for m in msgs)
        json_data = {"messages": msgs}
    elif rtype == 33:
        prio, weight, port = struct.unpack("!HHH", rdata[:6])
        target, _ = read_name(data, offset+6)
        txt_output = f'{prio} {weight} "{target}":{port}'
        json_data = {"priority": prio, "weight": weight, "port": port, "target": target}
    elif rtype == 6:
        mname, o1 = read_name(data, offset)
        rname, o2 = read_name(data, o1)
        serial, refresh, retry, expire, mini = struct.unpack("!IIIII", data[o2:o2+20])
        txt_output = f'"{mname}" "{rname}" {serial} {format_duration(refresh)} {format_duration(retry)} {format_duration(expire)} {format_duration(mini)}'
        json_data = {"mname": mname}
    elif rtype == 257:
        flags, tag_len = rdata[0], rdata[1]
        tag = rdata[2:2+tag_len].decode('ascii')
        val = rdata[2+tag_len:].decode('ascii')
        crit = "(critical)" if flags & 128 else "(non-critical)"
        txt_output = f'"{tag}" "{val}" {crit}'; json_data = {"flags": flags, "tag": tag, "value": val}
    elif rtype == 41:
        txt_output = f'{rdlength} 0 0 0 []'; json_data = {}
    else:
        txt_output = rdata.hex(); json_data = {"hex": rdata.hex()}
    return txt_output, json_data

def main():
    args = sys.argv[1:]
    domains, types, classes, nameservers = [], [], [], []
    txid, edns, tweaks = None, "hide", []
    protocol, short_mode, json_mode, color_mode = "udp", False, False, "automatic"
    time_mode, seconds_mode = False, False

    i = 0
    while i < len(args):
        arg = args[i]
        if arg == "--": pass
        elif arg in ("-q", "--query"):
            i += 1; domains.append(args[i])
        elif arg.startswith("--query="): domains.append(arg.split("=", 1)[1])
        elif arg in ("-t", "--type"):
            i += 1; types.append(args[i].upper())
        elif arg.startswith("--type="): types.append(arg.split("=", 1)[1].upper())
        elif arg in ("-n", "--nameserver"):
            i += 1; nameservers.append(args[i])
        elif arg.startswith("--nameserver="): nameservers.append(arg.split("=", 1)[1])
        elif arg.startswith("--class="): classes.append(arg.split("=", 1)[1].upper())
        elif arg.startswith("--edns="): edns = arg.split("=", 1)[1]
        elif arg.startswith("--txid="): txid = int(arg.split("=", 1)[1])
        elif arg.startswith("-Z="): tweaks.append(arg.split("=", 1)[1])
        elif arg in ("-U", "--udp"): protocol = "udp"
        elif arg in ("-T", "--tcp"): protocol = "tcp"
        elif arg in ("-S", "--tls"): protocol = "tls"
        elif arg in ("-H", "--https"): protocol = "https"
        elif arg in ("-1", "--short"): short_mode = True
        elif arg in ("-J", "--json"): json_mode = True
        elif arg in ("--color", "--colour"):
            i += 1; color_mode = args[i]
        elif arg.startswith("--color=") or arg.startswith("--colour="): color_mode = arg.split("=", 1)[1]
        elif arg == "--seconds": seconds_mode = True
        elif arg == "--time": time_mode = True
        elif arg in ("-?", "--help"): print(HELP_TEXT); sys.exit(0)
        elif arg in ("-v", "--version"): print("dog ● command-line DNS client\nv0.1.0"); sys.exit(0)
        else:
            if arg.startswith("@"): nameservers.append(arg[1:])
            elif arg.upper() in TYPES_CODES or arg.upper() in TYPES_LIST: types.append(arg.upper())
            elif arg.upper() in CLASSES_CODES: classes.append(arg.upper())
            else: domains.append(arg)
        i += 1

    if not domains: print(HELP_TEXT); sys.exit(3)
    if not types: types = ["A"]
    if not classes: classes = ["IN"]
    if not nameservers:
        try:
            with open('/etc/resolv.conf') as f:
                for line in f:
                    if line.startswith('nameserver '):
                        nameservers = [line.split()[1]]
                        break
        except: nameservers = ["8.8.8.8"]

    responses_json = []

    for domain in domains:
        for t in types:
            for c in classes:
                for ns in nameservers:
                    qtype = TYPES_CODES.get(t, 1)
                    qclass = CLASSES_CODES.get(c, 1)
                    tid = txid if txid is not None else random.randint(0, 65535)

                    flags = 0x0100
                    if "cd" in tweaks: flags |= 0x0010
                    if "ad" in tweaks: flags |= 0x0020

                    query = struct.pack("!H", tid)
                    query += struct.pack("!H", flags)
                    query += struct.pack("!H", 1) # QDCOUNT
                    query += struct.pack("!H", 0) # ANCOUNT
                    query += struct.pack("!H", 0) # NSCOUNT
                    query += struct.pack("!H", 1 if edns in ("show", "hide") else 0) # ARCOUNT

                    d_encoded = b""
                    for part in domain.strip(".").split("."):
                        d_encoded += struct.pack("!B", len(part))
                        d_encoded += part.encode("utf-8")
                    d_encoded += b"\x00"
                    query += d_encoded
                    query += struct.pack("!HH", qtype, qclass)

                    if edns in ("show", "hide"):
                        query += b"\x00"
                        query += struct.pack("!H", 41)
                        query += struct.pack("!H", 4096)
                        query += b"\x00\x00\x00\x00"
                        query += struct.pack("!H", 0)

                    start_time = time.time()
                    resp_data = b""
                    try:
                        if protocol == "udp":
                            sock = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
                            sock.settimeout(5)
                            sock.sendto(query, (ns, 53))
                            resp_data, _ = sock.recvfrom(4096)
                        elif protocol == "tcp":
                            sock = socket.create_connection((ns, 53), timeout=5)
                            sock.sendall(struct.pack("!H", len(query)) + query)
                            l = struct.unpack("!H", sock.recv(2))[0]
                            while len(resp_data) < l: resp_data += sock.recv(l - len(resp_data))
                        elif protocol == "tls":
                            ctx = ssl.create_default_context()
                            ctx.check_hostname = False; ctx.verify_mode = ssl.CERT_NONE
                            sock = socket.create_connection((ns, 853), timeout=5)
                            sock = ctx.wrap_socket(sock, server_hostname=ns)
                            sock.sendall(struct.pack("!H", len(query)) + query)
                            l = struct.unpack("!H", sock.recv(2))[0]
                            while len(resp_data) < l: resp_data += sock.recv(l - len(resp_data))
                        elif protocol == "https":
                            url = ns if ns.startswith("http") else f"https://{ns}/dns-query"
                            req = urllib.request.Request(url, data=query, headers={'Content-Type': 'application/dns-message', 'Accept': 'application/dns-message'})
                            ctx = ssl.create_default_context(); ctx.check_hostname = False; ctx.verify_mode = ssl.CERT_NONE
                            with urllib.request.urlopen(req, context=ctx, timeout=5) as response:
                                resp_data = response.read()
                    except Exception as e:
                        print(f"Error [network]: {e}", file=sys.stderr)
                        sys.exit(1)

                    end_time = time.time()

                    if not resp_data: continue

                    flags = struct.unpack("!H", resp_data[2:4])[0]
                    rcode = flags & 0x000F
                    qdcount, ancount, nscount, arcount = struct.unpack("!HHHH", resp_data[4:12])

                    offset = 12
                    for _ in range(qdcount):
                        _, offset = read_name(resp_data, offset)
                        offset += 4

                    j_answers, j_authorities, j_additionals = [], [], []
                    txt_records = []

                    def process_records(count, section_name, section_char, j_list):
                        nonlocal offset
                        for _ in range(count):
                            name, offset = read_name(resp_data, offset)
                            rt, rc, ttl, rdl = struct.unpack("!HHIH", resp_data[offset:offset+10])
                            offset += 10
                            txt_val, json_val = parse_rdata(rt, resp_data, offset, rdl)
                            offset += rdl

                            type_name = REV_TYPES.get(rt, f"TYPE{rt}")
                            class_name = REV_CLASSES.get(rc, f"CLASS{rc}")

                            if edns == "hide" and rt == 41:
                                continue

                            j_list.append({"name": name, "class": class_name, "ttl": ttl, "type": type_name, "data": json_val})
                            txt_records.append({
                                "type": type_name,
                                "domain": name,
                                "ttl_raw": ttl,
                                "section": section_char,
                                "data": txt_val
                            })

                    process_records(ancount, "answers", "   ", j_answers)
                    process_records(nscount, "authorities", " A ", j_authorities)
                    process_records(arcount, "additionals", " + ", j_additionals)

                    if json_mode:
                        responses_json.append({
                            "queries": [{"name": domain if domain.endswith(".") else domain+".", "class": c, "type": t}],
                            "answers": j_answers, "authorities": j_authorities, "additionals": j_additionals
                        })
                    else:
                        if short_mode:
                            for r in txt_records:
                                if r["section"] == "   ": print(r["data"])
                        else:
                            if rcode == 3: print("Status: NXDomain")
                            if txt_records:
                                max_type = max(len(r["type"]) for r in txt_records)
                                max_domain = max(len(r["domain"]) for r in txt_records)
                                for r in txt_records: r["ttl_str"] = str(r["ttl_raw"]) if seconds_mode else format_duration(r["ttl_raw"])
                                max_ttl = max(len(r["ttl_str"]) for r in txt_records)

                                for r in txt_records:
                                    ts = r["type"].rjust(max_type)
                                    ds = r["domain"].ljust(max_domain)
                                    ttl = r["ttl_str"].rjust(max_ttl)
                                    if color_mode == "always" or (color_mode == "automatic" and sys.stdout.isatty()):
                                        t_color = "\x1b[36m" if r["type"] == "MX" else "\x1b[33m" if r["type"] == "TXT" else "\x1b[1;32m"
                                        ts = f"{t_color}{ts}\x1b[0m"
                                        ds = f"\x1b[1;34m{ds}\x1b[0m"
                                    print(f"{ts} {ds} {ttl}{r['section']}{r['data']}")
                            if time_mode:
                                print(f"Ran in {int((end_time - start_time)*1000)}ms")

    if json_mode:
        print(json.dumps({"responses": responses_json}, separators=(',', ':')))

if __name__ == "__main__":
    main()
PYEOF
chmod +x executable
EOF
chmod +x compile.sh
./compile.sh
"}

